/**
 * Billing period arithmetic. Pure: no clock and no storage — callers pass the
 * instant they are working at, so the renewal job and the mid-period changes
 * agree on every boundary.
 */
import type { BillingInterval } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Months covered by one period of the given interval. */
export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * `start` moved forward by whole calendar months, keeping the time of day. A
 * target month without the same day clamps to its last day, so 31 January plus
 * one month is 28 February.
 */
export function addMonths(start: Date, months: number): Date {
  const year = start.getUTCFullYear();
  const targetMonth = start.getUTCMonth() + months;
  const lastDay = new Date(Date.UTC(year, targetMonth + 1, 0)).getUTCDate();

  const next = new Date(start.getTime());
  next.setUTCFullYear(year, targetMonth, Math.min(start.getUTCDate(), lastDay));
  return next;
}

/** The end of a period that starts at `start` and lasts one interval. */
export function periodEndFor(start: Date, interval: BillingInterval): Date {
  return addMonths(start, monthsIn(interval));
}

/** Whole days between a period's start and end, never less than one. */
export function daysInPeriod(periodStart: Date, periodEnd: Date): number {
  return Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / MS_PER_DAY),
  );
}

/** Whole or started days from `now` to the period end; zero once it is reached. */
export function daysLeft(now: Date, periodEnd: Date): number {
  const remaining = periodEnd.getTime() - now.getTime();
  return remaining <= 0 ? 0 : Math.ceil(remaining / MS_PER_DAY);
}

/**
 * Full-period charge for `seats` at `pricePerSeatMonthly`, over one interval.
 * Used for renewals and for the full-period amount of a mid-period change.
 */
export function fullPeriodCharge(
  pricePerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return pricePerSeatMonthly * seats * monthsIn(interval);
}

/**
 * The share of a full-period amount that covers the rest of the period from
 * `now`, rounded down to whole cents.
 */
export function prorate(
  fullAmountCents: number,
  periodStart: Date,
  periodEnd: Date,
  now: Date,
): number {
  const days = daysInPeriod(periodStart, periodEnd);
  const left = Math.min(days, daysLeft(now, periodEnd));
  return Math.floor((fullAmountCents * left) / days);
}

