 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 *
 * Moving between paid plans on an active subscription charges the price
 * difference for the rest of the period; leaving the free plan starts a fresh
 * period and charges it in full; a trial keeps its period and charges nothing.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const currentPlan = subscription.plan;

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const now = new Date();
  const seats = subscription.seats;
  let newPeriod: { start: IsoTimestamp; end: IsoTimestamp } | null = null;
  let charge: { amountCents: number; periodStart: IsoTimestamp; periodEnd: IsoTimestamp } | null = null;

  const chargeable =
    subscription.status === "active" &&
    input.plan !== currentPlan &&
    input.plan !== "free";

  if (chargeable && currentPlan === "free") {
    const start = toIsoTimestamp(now);
    const end = toIsoTimestamp(periodEndFor(now, input.interval));
    newPeriod = { start, end };
    charge = {
      amountCents: fullPeriodCharge(
        getPlanLimits(input.plan).priceCentsPerSeatMonthly,
        seats,
        input.interval,
      ),
      periodStart: start,
      periodEnd: end,
    };
  } else if (chargeable) {
    const priceDifference =
      getPlanLimits(input.plan).priceCentsPerSeatMonthly -
      getPlanLimits(currentPlan).priceCentsPerSeatMonthly;
    if (priceDifference > 0) {
      charge = {
        amountCents: prorate(
          fullPeriodCharge(priceDifference, seats, subscription.interval),
          new Date(subscription.currentPeriodStart),
          new Date(subscription.currentPeriodEnd),
          now,
        ),
        periodStart: subscription.currentPeriodStart,
        periodEnd: subscription.currentPeriodEnd,
      };
    }
  }

  const updated = await subscriptionRepo.updateSubscriptionPlan(
    input.orgId,
    input.plan,
    input.interval,
    newPeriod,
  );

  if (charge !== null && charge.amountCents > 0) {
    await issueInvoice(
      input.orgId,
      {
        periodStart: charge.periodStart,
        periodEnd: charge.periodEnd,
        amountCents: charge.amountCents,
      },
      now,
    );
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return updated;
}

/**
 * Adding seats to a paid, active subscription charges the added seats for the
 * rest of the period. Removing seats charges and credits nothing.
 */
export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const plan = await planFor(input.orgId);

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  const now = new Date();
  const addedSeats = input.seats - subscription.seats;
  const chargeable =
    subscription.status === "active" && plan !== "free" && addedSeats > 0;

  const amountCents = chargeable
    ? prorate(
        fullPeriodCharge(
          getPlanLimits(plan).priceCentsPerSeatMonthly,
          addedSeats,
          subscription.interval,
        ),
        new Date(subscription.currentPeriodStart),
        new Date(subscription.currentPeriodEnd),
        now,
      )
    : 0;

  const updated = await subscriptionRepo.updateSeatCount(
    input.orgId,
    input.seats,
  );

  if (amountCents > 0) {
    await issueInvoice(
      input.orgId,
      {
        periodStart: subscription.currentPeriodStart,
        periodEnd: subscription.currentPeriodEnd,
        amountCents,
      },
      now,
    );
  }

  return updated;
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

/**
 * Issues one invoice for a period and announces it. Publishing the event is
 * what writes the audit row and notifies the owner, so every caller gets the
 * same bookkeeping.
 */
export async function issueInvoice(
  orgId: OrgId,
  period: {
    periodStart: IsoTimestamp;
    periodEnd: IsoTimestamp;
    amountCents: number;
  },
  now: Date,
): Promise<Invoice> {
  const issued = await invoiceRepo.countInvoices(orgId);
  const invoice = await invoiceRepo.insertInvoice(orgId, {
    orgId,
    number: formatInvoiceNumber(issued + 1),
    amountCents: period.amountCents,
    currency: "usd",
    periodStart: period.periodStart,
    periodEnd: period.periodEnd,
    paidAt: null,
  });

  await emit("billing.invoice_issued", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(now),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  return invoice;
}

function formatInvoiceNumber(sequence: number): string {
  return `INV-${String(sequence).padStart(6, "0")}`;
}

