/**
 * Renews subscriptions whose period has ended, invoices every renewed paid
 * period and ends cancellations that have reached their date.
 *
 * Must call (do not reimplement): emit, getPlanLimits, periodEndFor, fullPeriodCharge, issueInvoice
 */
import { getPlanLimits } from "@/config/plan-limits";
import { fullPeriodCharge, periodEndFor } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

/** Subscriptions read per keyset page. */
const PAGE_SIZE = 100;

const logger = createLogger("billing-renewal-job");

/**
 * Sweeps every live workspace's subscription. Each subscription is handled on
 * its own: a failure is logged and counted, and the sweep carries on. Replay
 * safe — once a period is advanced it no longer ends at or before `now`, so a
 * second pass at the same instant finds nothing to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    let cursor: string | null = null;

    for (;;) {
      const page: readonly Subscription[] =
        await subscriptionRepo.listLiveSubscriptionsPage(cursor, PAGE_SIZE);

      for (const subscription of page) {
        cursor = subscription.id;

        try {
          if (await processSubscription(subscription, now)) {
            result.processed += 1;
          }
        } catch (error) {
          result.failed += 1;
          logger.error("billing renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      if (page.length < PAGE_SIZE) break;
    }
  });
}

/** Returns true when the subscription changed. Trials and past-due are left alone. */
async function processSubscription(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.status === "active") {
    return renewPeriods(subscription, now);
  }

  if (subscription.status === "canceled") {
    return endCancellation(subscription, now);
  }

  return false;
}

/**
 * Walks the subscription forward one period at a time until its period end
 * lies after `now`. Each paid period is invoiced at the seat count of that
 * moment. The invoice is written before the period moves on, and a renewal
 * invoice that already exists for a period start is not written twice, so a
 * crash between the two steps cannot double-bill.
 */
async function renewPeriods(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (new Date(subscription.currentPeriodEnd) > now) return false;

  const paid = subscription.plan !== "free";
  const pricePerSeat = getPlanLimits(subscription.plan).priceCentsPerSeatMonthly;
  let start = new Date(subscription.currentPeriodEnd);

  while (start <= now) {
    const end = periodEndFor(start, subscription.interval);
    const periodStart = toIsoTimestamp(start);
    const periodEnd = toIsoTimestamp(end);

    if (
      paid &&
      (await invoiceRepo.findInvoiceStartingAt(subscription.orgId, periodStart)) ===
        null
    ) {
      await issueInvoice(
        subscription.orgId,
        {
          periodStart,
          periodEnd,
          amountCents: fullPeriodCharge(
            pricePerSeat,
            subscription.seats,
            subscription.interval,
          ),
        },
        now,
      );
    }

    await subscriptionRepo.setSubscriptionPeriod(
      subscription.orgId,
      periodStart,
      periodEnd,
    );
    start = end;
  }

  return true;
}

/**
 * A cancellation whose date has arrived moves the workspace to the free plan
 * as of that date, announces the change once, and then runs the free plan's
 * periods forward to the present like any other active subscription.
 */
async function endCancellation(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.cancelAt === null) return false;

  const cancelAt = new Date(subscription.cancelAt);
  if (cancelAt > now) return false;

  const periodStart: IsoTimestamp = toIsoTimestamp(cancelAt);
  const periodEnd: IsoTimestamp = toIsoTimestamp(periodEndFor(cancelAt, "monthly"));

  await subscriptionRepo.moveSubscriptionToFree(
    subscription.orgId,
    periodStart,
    periodEnd,
  );

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: periodStart,
    from: subscription.plan,
    to: "free",
  });

  await renewPeriods(
    {
      ...subscription,
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
    },
    now,
  );

  return true;
}
